def nearestPalindrome(n):
    s = str(n)
    L = len(s)
    half = (L + 1) // 2
    pre = int(s[:half])
    cands = {10 ** (L - 1) - 1, 10 ** L + 1}
    for d in (-1, 0, 1):
        q = str(pre + d)
        if len(q) != half:
            continue
        cands.add(int(q + q[-2::-1]) if L % 2 else int(q + q[::-1]))
    best = None
    for c in cands:
        if c < 1 or c == n:
            continue
        key = (abs(c - n), c)
        if best is None or key < best:
            best = key
    return best[1]
